static int entityType(const QString&t){if(t=="Sprite")return 1;if(t=="Mesh")return 2;if(t=="Camera")return 3;if(t=="Light")return 4;if(t=="Text")return 5;if(t=="Panel")return 6;if(t=="Button")return 7;if(t=="Image")return 8;if(t=="AudioSource")return 9;return 0;}
static QString cpp(QString s){s.replace("\\","\\\\");s.replace("\"","\\\"");s.replace("\n","\\n");s.replace("\r","\\r");return "\""+s+"\"";} static QString cstrAsset(const QString&s){return s.isEmpty()?"nullptr":cpp(QFileInfo(s).fileName());} static QString cstrLiteral(const QString&s){return s.isEmpty()?"nullptr":cpp(s);} static QString f32(float v){return QString::number(v,'f',6)+"f";}

