    m_watcher=new QFileSystemWatcher(this);connect(m_watcher,&QFileSystemWatcher::fileChanged,this,&MainWindow::onWatchedPathChanged);connect(m_watcher,&QFileSystemWatcher::directoryChanged,this,&MainWindow::onWatchedPathChanged);
    auto pipe=[this](QProcess*q){connect(q,&QProcess::readyReadStandardOutput,this,[this,q]{appendOutput(QString::fromLocal8Bit(q->readAllStandardOutput()));});connect(q,&QProcess::readyReadStandardError,this,[this,q]{appendOutput(QString::fromLocal8Bit(q->readAllStandardError()));});};pipe(m_process);connect(m_runProcess,&QProcess::readyReadStandardOutput,this,[this]{QString t=QString::fromLocal8Bit(m_runProcess->readAllStandardOutput());appendOutput(t);if(m_profiler)m_profiler->ingestRuntimeOutput(t);});connect(m_runProcess,&QProcess::readyReadStandardError,this,[this]{QString t=QString::fromLocal8Bit(m_runProcess->readAllStandardError());appendOutput(t);if(m_profiler)m_profiler->ingestRuntimeOutput(t);});
    connect(m_process,qOverload<int,QProcess::ExitStatus>(&QProcess::finished),this,[this](int c,QProcess::ExitStatus){appendOutput(QString("\nBuild/tool process finished with code %1\n").arg(c));if(m_runAfterBuild){bool run=(c==0);m_runAfterBuild=false;if(run)runPCSX2();}});
    connect(m_scene,&SceneDocument::changed,this,[this]{m_sceneDirty=true;refreshHierarchy();});connect(m_scene,&SceneDocument::changed,m_profiler,&ProfilerWidget::refresh);connect(m_assetDb,&AssetDatabase::changed,this,&MainWindow::refreshAssets);m_clangd->setDiagnosticsCallback([this](QString file,QList<ClangdDiagnostic> ds){m_diagnostics[file]=ds;QList<PS2StudioProblem> all;for(auto it=m_diagnostics.cbegin();it!=m_diagnostics.cend();++it)for(const auto&d:it.value()){PS2StudioProblem p;p.file=d.file;p.line=d.line;p.column=d.column;p.severity=d.severity;p.message=d.message;p.source=d.source;all<<p;}if(m_problems){m_problems->setProblems(all);if(!all.isEmpty())m_problemsDock->show();}for(int i=0;i<m_editorTabs->count();++i){auto*ed=dynamic_cast<CodeEditor*>(m_editorTabs->widget(i));if(!ed||ed->filePath()!=file)continue;QHash<int,int> lines;for(const auto&d:ds)lines[d.line]=d.severity;ed->setDiagnosticLines(lines);}});
